--
-- Table structure for table `membership`
--

DROP TABLE IF EXISTS `membership`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `membership` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_profile_id` int NOT NULL,
  `plan_id` int NOT NULL,
  `payment_order_id` bigint DEFAULT NULL,
  `promo_id` int DEFAULT NULL,
  `source` varchar(24) NOT NULL DEFAULT 'PURCHASE',
  `starts_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` datetime DEFAULT NULL,
  `status` varchar(24) NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_membership_user_status` (`user_profile_id`,`status`),
  KEY `idx_membership_expiry` (`status`,`expires_at`),
  KEY `fk_membership_plan` (`plan_id`),
  KEY `fk_membership_order` (`payment_order_id`),
  KEY `fk_membership_promo` (`promo_id`),
  CONSTRAINT `fk_membership_order` FOREIGN KEY (`payment_order_id`) REFERENCES `payment_order` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_membership_plan` FOREIGN KEY (`plan_id`) REFERENCES `subscription_plan` (`id`),
  CONSTRAINT `fk_membership_promo` FOREIGN KEY (`promo_id`) REFERENCES `promo_campaign` (`id`),
  CONSTRAINT `fk_membership_user` FOREIGN KEY (`user_profile_id`) REFERENCES `user_profile` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

